-- 4/5 وصفات الحساب (1)
BEGIN;
DO $do$
DECLARE
  d jsonb := $rt$[{"kind":"breakfast","title":"كلوب ساندوتش البيض والتيركي","method":"المكونات:\n• 58غ توست (3 شرائح)\n• 2 بيضة كاملة + 2 بياض بيض\n• 50غ شرائح تيركي (ديك رومي)\n• 25غ جبن قشقوان\n• 19غ جبن شرائح\n• 36غ طماطم شرائح\n• 15غ مايونيز\n• 11غ صلصة رانش\n• خس\n\nالطريقة:\n1. نحمّص التوست، ونطبخ البيض بالمقلاة كعجة رقيقة.\n2. الطبقة الأولى: توست مدهون بالمايونيز ثم خس وبيض وجبن قشقوان.\n3. الطبقة الثانية: توست ثم تيركي وطماطم وجبن شرائح.\n4. نقفلها بآخر توستة مدهونة بالرانش، ونقطعها مثلثات.\n\nالألياف: 2غ\n\nملاحظة: محسوبة بمايونيز ورانش وجبن عاديين؛ لو استخدمتي النسخ الخفيفة تقل الدهون والسعرات. قشقوان محسوب ببديله الأقرب في USDA (بروفولون). البطاطس الجانبية غير محسوبة. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"كلوب ساندوتش البيض والتيركي","portion":"ساندوتش كامل","protein":50.5,"carbs":33.4,"fat":41.3}]},{"kind":"lunch","title":"دجاج ماسالا بالزبادي مع رز","method":"المكونات:\n• 373غ صدر دجاج فيليه (نيء) — للحصتين\n• 72غ بصل\n• 9غ ثوم\n• 150غ زبادي يوناني (نصه للتتبيلة ونصه لسلطة الخيار)\n• 17غ صلصة/معجون طماطم\n• 75غ كريمة طبخ\n• 80غ رز قبل الطبخ\n• بهارات: زنجبيل، ثوم وبصل بودرة، بهارات دجاج وهندية، كاري، كركم، زعفران، فلفل مجروش، ملح\n\nالطريقة:\n1. نتبّل الدجاج بنص الزبادي اليوناني والبهارات ونتركه نص ساعة.\n2. على صاج حار وبدون زيت نحمّر الثوم والبصل لين يذبلون.\n3. نضيف الدجاج بتتبيلته ونقلّبه لين يستوي، وآخر شيء نضيف صلصة الطماطم وكريمة الطبخ.\n4. نغسل الرز كويس وننقعه 10 دقايق قبل الطبخ عشان يطلع منثور.\n5. سلطة جانبية: باقي الزبادي مع خيار مبشور مصفّى وملح وليمون.\n\nالألياف: 1.6غ\n\nملاحظة: صلصة الطماطم محسوبة كمعجون طماطم (17غ). الخيار غير محسوب. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"دجاج ماسالا بالزبادي مع رز","portion":"حصة (الوصفة لحصتين)","protein":54.5,"carbs":42.8,"fat":13.8}]},{"kind":"breakfast","title":"عريكة جنوبية صحية","method":"المكونات:\n• 40غ دقيق بر (أسمر)\n• 4غ زبدة\n• 55غ تمر (خلاص)\n• 150مل ماء حار\n• هيل وزنجبيل مطحون وذرة ملح\n• سكر ستيفيا (اختياري)\n\nالطريقة:\n1. نحمّص الدقيق على النار لين يتغير لونه.\n2. ننقع 40غ من التمر بالماء الحار، ونسخّنه دقيقة بالمايكرويف ونهرسه.\n3. نضيف التمر للدقيق على الصاج ونعصده مع الهيل والزنجبيل والملح لين يتماسك.\n4. نصبّه بالصحن ونحط الزبدة الذايبة بالوسط، ونزيّنه بباقي التمر.\n\nالألياف: 8.7غ\n\nملاحظة: تمر الخلاص محسوب بقيم تمر دقلة نور (الأقرب في USDA). القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"عريكة جنوبية صحية","portion":"صحن","protein":6.7,"carbs":70.1,"fat":4.5}]},{"kind":"lunch","title":"برجر المطاعم بطريقة صحية مع بطاطس","method":"المكونات:\n• 232غ لحم مفروم (نيء)\n• 239غ بطاطس\n• 51غ خبز بريوش\n• 40غ جبن شرائح\n• 24غ طماطم\n• الصوص: 100غ زبادي يوناني + 16غ كاتشب + 16غ خردل + 16غ مايو\n• خس ومخلل\n• فلفل أسود، ملح، بابريكا، ثوم وبصل بودرة، بهارات إيطالية، كيجن، ماء المخلل\n\nالطريقة:\n1. نبهّر اللحم بالملح والفلفل الأسود، ونشكّله أقراص.\n2. نشويه على صاج حار جداً من الجهتين، ونحط عليه الجبن آخر دقيقة لين يذوب.\n3. نخلط مكونات الصوص مع البهارات وماء المخلل.\n4. نقطّع البطاطس ونبهّرها بنفس البهارات، ونطبخها بالقلاية الهوائية حوالي 20 دقيقة.\n5. نركّب: خبز، صوص، خس، لحم بالجبن، مخلل، طماطم، صوص، ونقفل.\n\nالألياف: 7.2غ\n\nملاحظة: اللحم محسوب كمفروم بقري 90% (المنشور ما حدد نسبة الدهن)، والبريوش بقيم خبز البيض في USDA. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"برجر المطاعم بطريقة صحية مع بطاطس","portion":"وجبة كاملة","protein":74.6,"carbs":78.4,"fat":53.3}]},{"kind":"lunch","title":"فوتشيني دجاج بالكريمة الخفيفة","method":"المكونات:\n• 297غ صدر دجاج (نيء)\n• 60غ فوتشيني قبل الطبخ\n• 66غ جبن فيلادلفيا لايت\n• 6غ ثوم\n• فلفل أسود، ثوم وبصل بودرة، ملح، فلفل مجروش، بهارات إيطالية\n\nالطريقة:\n1. نبهّر الدجاج ونشويه على الصاج من الجهتين، ونرفعه.\n2. بنفس الصاج نحمّر الثوم، ونضيف جبن الفيلادلفيا وشوي من مويا سلق المكرونة لين يصير صوص كريمي.\n3. نخلط المكرونة بالصوص.\n4. نقطّع الدجاج بعد ما يبرد شوي ونحطه فوق، مع فلفل مجروش وبهارات إيطالية.\n\nالألياف: 2غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"فوتشيني دجاج بالكريمة الخفيفة","portion":"وجبة كاملة","protein":80.2,"carbs":51.2,"fat":19.7}]},{"kind":"lunch","title":"باستا بارميزان بينك بالدجاج المشوي","method":"المكونات:\n• 65غ باستا قبل الطبخ\n• 5غ ثوم\n• 37غ طماطم مهروسة\n• 17غ بارميزان\n• 15غ موزاريلا\n• 50غ جبن فيلادلفيا لايت\n• 298غ صدر دجاج (نيء)\n• ثوم وبصل بودرة، بابريكا، ملح، فلفل أسود ومجروش، بهارات دجاج\n\nالطريقة:\n1. نضرب الدجاج لين يصير رقيق ونبهّره، ونشويه على صاج أو شواية حارة 15 دقيقة كحد أقصى حسب سماكته، ونتركه يبرد قبل التقطيع.\n2. نحمّر الثوم المهروس، ونضيف الطماطم ومويا الباستا وجبن الفيلادلفيا ونتركها تتسبك.\n3. نضيف الباستا والبارميزان والموزاريلا ونقلّب.\n4. نقدّمها مع الدجاج ورشة بارميزان.\n\nالألياف: 2.6غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"باستا بارميزان بينك بالدجاج المشوي","portion":"وجبة كاملة","protein":88.6,"carbs":57.8,"fat":24.3}]},{"kind":"snack","title":"بودنق الحليب المحموس بالشوكولاتة","method":"المكونات:\n• الكيك: 30غ شوفان مطحون، 7غ كاكاو، 5غ باكنج باودر، 10غ بروتين باودر، بيضة (52غ)، 32غ زبادي يوناني، سكر نولا، 20مل ماء\n• الطبقة الثانية: 12غ دريم ويب، 72غ فيلادلفيا لايت، سكر نولا، 14غ حليب بودرة محموس\n• الطبقة الثالثة: 27غ بسكويت مطحون\n• الطبقة الرابعة: 40غ شوكولاتة بالحليب\n\nالطريقة:\n1. نحمّس حليب البودرة على النار لين يصير ذهبي.\n2. نخلط مكونات الكيك ونخبزه بفرن مسبق التسخين 12 دقيقة (10 من تحت ودقيقتين من فوق).\n3. نخفق الدريم ويب مع جبن الفيلادلفيا والسكر والحليب المحموس ونوزّعه فوق الكيك.\n4. نرش البسكويت المطحون، ثم الشوكولاتة الذايبة، ونقسمه 4 حصص.\n\nالألياف: 2غ\n\nملاحظة: الكميات للصينية كاملة (4 حصص) والقيم للحصة. البسكويت والشوكولاتة والدريم ويب محسوبة ببدائل عامة من USDA. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"بودنق الحليب المحموس بالشوكولاتة","portion":"حصة (من 4 حصص)","protein":9.3,"carbs":23.4,"fat":10.1}]},{"kind":"snack","title":"سوفلية الشوكولاتة السريعة","method":"المكونات:\n• 100مل حليب بروتين ندى\n• 56غ بسكويت بدون كريمة\n• 2غ باكنج باودر\n• 30مل ماء\n\nالطريقة:\n1. نخلط كل المكونات بالخلاط مع الماء.\n2. نوزّعها على كاستين صغار.\n3. نطبخها بالقلاية الهوائية 6 دقايق على 180°.\n\nالألياف: 1غ\n\nملاحظة: بسكويت جالون محسوب ببديل عام (بسكويت سادة) من USDA. القيم محسوبة من المكونات بقاعدة بيانات USDA (وحليب البروتين من موقع ندى). التوابل والمحليات الخالية من السعرات غير محسوبة. فكرة الوصفة والكميات من حساب @healthy_shody (الصحية شهد).","items":[{"food":"سوفلية الشوكولاتة السريعة","portion":"حصة (الوصفة لحصتين)","protein":6.1,"carbs":26.3,"fat":3}]}]$rt$;
  m jsonb; it jsonb; v_plan uuid; v_meal uuid; j int; k int;
BEGIN
  SELECT id INTO v_plan FROM nutrition_plans WHERE order_id IS NULL AND is_library;
  IF v_plan IS NULL THEN RAISE EXCEPTION 'مكتبة الوجبات غير موجودة. شغّلي ملف meal-library أولاً.'; END IF;
  j := coalesce((SELECT max(position) + 1 FROM plan_meals WHERE plan_id = v_plan), 0);
  FOR m IN SELECT * FROM jsonb_array_elements(d) LOOP
    CONTINUE WHEN EXISTS (SELECT 1 FROM plan_meals WHERE plan_id = v_plan AND title = m->>'title');
    INSERT INTO plan_meals (plan_id, kind, title, method, position) VALUES (v_plan, m->>'kind', m->>'title', nullif(m->>'method', ''), j) RETURNING id INTO v_meal;
    k := 0;
    FOR it IN SELECT * FROM jsonb_array_elements(m->'items') LOOP
      INSERT INTO plan_items (meal_id, food, portion, protein, carbs, fat, position)
      VALUES (v_meal, it->>'food', nullif(it->>'portion', ''), (it->>'protein')::numeric, (it->>'carbs')::numeric, (it->>'fat')::numeric, k);
      k := k + 1;
    END LOOP;
    j := j + 1;
  END LOOP;
  UPDATE nutrition_plans SET notes = regexp_replace(coalesce(notes, ''), '[0-9]+ وجبة', (SELECT count(*) FROM plan_meals WHERE plan_id = v_plan) || ' وجبة'), updated_at = now() WHERE id = v_plan;
END $do$;

COMMIT;
